#!/bin/sh
# Butter (= vA Tree) builds:
#  1. docs/ext-ai/vA-external-ai-tree.js  - the outside AI package (かんたんインストール / link page)
#  2. tools/patch/ai-src/engine/butter-preinstalled.js - the same package registered at start in vA (built in),
#     plus the in-app learning panel (app-ui.js)
#  3. tools/patch/ai-src/engine/butter-learn.js - the learner Worker (MP4 tool engine + learn-core.mjs)
set -e
HUB="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$HOME/Downloads/tetrio-replay-video"
E="npx --prefix tools esbuild"
$E "$HUB/tools/butter/package-entry.js" --bundle --format=iife --platform=browser --log-level=warning --outfile="$HUB/docs/ext-ai/vA-external-ai-tree.js"
$E "$HUB/tools/butter/learn-worker.js" --bundle --format=iife --platform=browser --target=es2022 --alias:chalk=./vendor/triangle/chalk-stub.js --minify --legal-comments=eof --log-level=warning --outfile="$HUB/tools/patch/ai-src/engine/butter-learn.js"
node -e '
const fs=require("fs"),hub=process.argv[1],pkg=fs.readFileSync(hub+"/docs/ext-ai/vA-external-ai-tree.js","utf8"),ui=fs.readFileSync(hub+"/tools/butter/app-ui.js","utf8");
const out="/* vA: Butter (= vA Tree) built in (generated by tools/butter/build.sh; do not edit). Registered at start like an installed\n   outside AI (its own script text, so it runs in a Worker). Name: \"vATree\" auto-converted to \"butter\". */\n(()=>{const A=window.LocalExternalAI;if(!A)return;const SCRIPT="+JSON.stringify(pkg)+";\nconst real=A.register;A.register=d=>real({...d,files:{},script:SCRIPT});try{\n"+pkg+"\n}finally{A.register=real}\n"+ui+"\n})();\n";
fs.writeFileSync(hub+"/tools/patch/ai-src/engine/butter-preinstalled.js",out);' "$HUB"
ls -la "$HUB/docs/ext-ai/vA-external-ai-tree.js" "$HUB/tools/patch/ai-src/engine/butter-preinstalled.js" "$HUB/tools/patch/ai-src/engine/butter-learn.js"
